import{_ as s,C as a,c as n,o as d,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Orders report","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/reporting/orders-report.md","filePath":"master/sales/point-of-sale/reporting/orders-report.md","lastUpdated":1792041590000}'),l={name:"master/sales/point-of-sale/reporting/orders-report.md"};function i(h,e,p,m,g,u){const r=a("ImagePopup");return d(),n("div",null,[e[0]||(e[0]=t('<h1 id="orders-report" tabindex="-1">Orders report <a class="header-anchor" href="#orders-report" aria-label="Permalink to &quot;Orders report&quot;">​</a></h1><p>The Orders report counts your settled orders and groups them by day, week or month. For each group it shows the untaxed amount, the taxes, the total and the margin. Use it to see how your sales move over time and to spot slow or busy periods.</p><blockquote><p><strong>In simple words:</strong> This report answers &quot;how many orders did I take, and how much did they bring in, per day, week or month?&quot;</p></blockquote><h2 id="open-the-report" tabindex="-1">Open the report <a class="header-anchor" href="#open-the-report" aria-label="Permalink to &quot;Open the report&quot;">​</a></h2><p>Go to <code>Point of Sale → Reporting → Orders</code>. The page title is <strong>Order Analysis</strong>. You can also reach it from the three-dot menu of a register card, under <strong>Reporting → Orders</strong>. That link opens the report already filtered for that register.</p>',5)),o(r,{src:"/images1/pos/orders_report_by_day.png",alt:"Order Analysis page with dates 01/10/2026 to 12/10/2026, All terminals and By day, showing one row for 2026-10-12 with 3 orders and total 6,597.00"}),e[1]||(e[1]=t('<h2 id="set-the-filters" tabindex="-1">Set the filters <a class="header-anchor" href="#set-the-filters" aria-label="Permalink to &quot;Set the filters&quot;">​</a></h2><p>The filter bar has four fields, from left to right.</p><ol><li><strong><em>Start date:</em></strong> The first day to include. It starts on the first day of the current month.</li><li><strong><em>End date:</em></strong> The last day to include. It starts on today.</li><li><strong><em>Terminal:</em></strong> Choose <strong>All terminals</strong> or one register, for example <strong>TechNest Electronics</strong>.</li><li><strong><em>Grouping:</em></strong> Choose <strong>By day</strong>, <strong>By week</strong> or <strong>By month</strong>.</li></ol><p>The table refreshes as soon as you change a field.</p>',4)),o(r,{src:"/images1/pos/orders_report_filters.png",alt:"Filter bar of the Order Analysis page with the start date, end date, TechNest Electronics selected and By month selected"}),e[2]||(e[2]=t('<h2 id="read-the-table" tabindex="-1">Read the table <a class="header-anchor" href="#read-the-table" aria-label="Permalink to &quot;Read the table&quot;">​</a></h2><p>Each row is one period. The columns are:</p><ul><li><strong><em>Period:</em></strong> The day (2026-10-12), the ISO week (2026-W42) or the month (2026-10).</li><li><strong><em>Orders:</em></strong> How many settled orders fall in this period.</li><li><strong><em>Untaxed:</em></strong> The sum of order amounts before tax.</li><li><strong><em>Taxes:</em></strong> The sum of tax on those orders.</li><li><strong><em>Total:</em></strong> Untaxed plus taxes.</li><li><strong><em>Margin:</em></strong> The profit margin of the orders, added up for the period.</li></ul><p>The last row, <strong>Total</strong>, adds up every column. Below the table you see <strong>Average order value</strong>, which is the total divided by the number of orders.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Only orders with status Paid, Posted or Invoiced are counted. Refund orders count too, with negative amounts.</p></div><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p>Take the sample data, all created on 12 October 2026, with <strong>All terminals</strong> and <strong>By day</strong>.</p><table tabindex="0"><thead><tr><th>Period</th><th>Orders</th><th>Untaxed</th><th>Taxes</th><th>Total</th><th>Margin</th></tr></thead><tbody><tr><td>2026-10-12</td><td>3</td><td>6,597.00</td><td>0.00</td><td>6,597.00</td><td>2,897.00</td></tr><tr><td><strong>Total</strong></td><td>3</td><td>6,597.00</td><td>0.00</td><td>6,597.00</td><td>2,897.00</td></tr></tbody></table><p>The three orders are TNE/00001, TNE/00002 and the refund of TNE/00002. The smartphone sale and its refund cancel each other. The average order value is 6,597.00 divided by 3, which is 2,199.00.</p><p>Switch <strong>By day</strong> to <strong>By month</strong>. The table shows one row, 2026-10, with the same numbers.</p>',10)),o(r,{src:"/images1/pos/orders_report_by_month.png",alt:"Order Analysis grouped By month showing one row 2026-10 with 3 orders and total 6,597.00 and Average order value 2,199.00"}),e[3]||(e[3]=t('<h2 id="common-questions" tabindex="-1">Common questions <a class="header-anchor" href="#common-questions" aria-label="Permalink to &quot;Common questions&quot;">​</a></h2><p><strong>Why is my order missing?</strong> Check its status. A <strong>New</strong> or <strong>Cancelled</strong> order is not counted. Also check that the order date is inside the range.</p><p><strong>Why is the count higher than the number of sales I made?</strong> Each refund is an order. One sale plus one refund counts as two.</p><p><strong>Can I see which products were sold?</strong> Yes. Use <a href="./sales-details.html">Sales details</a> for products, payments and taxes.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Reporting overview</a></li><li><a href="./sales-details.html">Sales details</a></li><li><a href="./../selling/refunds.html">Refunds</a></li><li><a href="./../orders-payments/orders.html">Orders</a></li></ul>',6))])}const _=s(l,[["render",i]]);export{f as __pageData,_ as default};
